(()=>{const workspace=document.querySelector('.workspace'),bar=document.querySelector('.bar'),table=document.querySelector('.tablewrap'),panel=document.querySelector('.panel');const toolbar=document.createElement('div');toolbar.className='wk-toolbar';toolbar.innerHTML='<div class="tools"><input id="staffSearch" placeholder="⌕  Tìm nhân sự..." aria-label="Tìm nhân sự"><select id="staffFilter"><option value="all">Tất cả nhân sự</option><option value="assigned">Đã phân công</option><option value="pending">Chờ xếp ca</option><option value="empty">Chưa có lịch</option></select><span id="staffShown" class="wk-pill">17 nhân sự</span></div><div class="legend"><span><b class="green"></b>Đã phân công</span><span><b class="gold"></b>Đã đăng ký</span><span><b class="purple"></b>Đang chọn</span></div>';workspace.parentNode.insertBefore(toolbar,workspace);const caption=document.createElement('div');caption.className='wk-caption';caption.textContent='Chọn một ô để phân công · Cuộn bảng để xem toàn bộ nhân sự · Prototype không ghi Production';workspace.parentNode.insertBefore(caption,workspace.nextSibling);const av=document.getElementById('availability');av.classList.add('availability-box');const search=document.getElementById('staffSearch'),filter=document.getElementById('staffFilter');function applyFilter(){let visible=0;document.querySelectorAll('#grid tr').forEach((row,i)=>{let text=names[i].toLocaleLowerCase('vi');let status=Array.from(row.querySelectorAll('.chip'));let hasAssigned=status.some(x=>x.classList.contains('assigned'));let hasPending=status.some(x=>x.classList.contains('pending'));let f=filter.value;let show=text.includes(search.value.trim().toLocaleLowerCase('vi'))&&(f==='all'||(f==='assigned'&&hasAssigned)||(f==='pending'&&hasPending)||(f==='empty'&&!hasAssigned&&!hasPending));row.classList.toggle('wk-filter-hidden',!show);if(show)visible++;row.cells[0].classList.toggle('wk-selected',selected[0]===i)});document.getElementById('staffShown').textContent=visible+' / '+names.length+' nhân sự'}search.addEventListener('input',applyFilter);filter.addEventListener('change',applyFilter);const oldRender=render;render=function(){oldRender();applyFilter()};const oldChoose=choose;choose=function(i,j){oldChoose(i,j);applyFilter()};function updateDates(){let config=JSON.parse(localStorage.getItem('pino-workforce-v2-config')||'null');let query=new URLSearchParams(location.search).get('termweek');let label=document.getElementById('weekLabel').textContent;let chosen=config?.weeks?.find(w=>w.from===query)||config?.weeks?.find(w=>label.includes(w.name)&&w.name);let from=chosen?.from||'2026-10-12';let d=new Date(from+'T12:00:00');document.querySelectorAll('.tablewrap thead th').forEach((th,i)=>{if(!i)return;let date=new Date(d);date.setDate(date.getDate()+i-1);th.innerHTML=['','Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','CN'][i]+'<span class="daydate">'+date.toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit'})+'</span>'})}const oldWeek=changeWeek;changeWeek=function(n){oldWeek(n);updateDates()};const oldSelect=window.choose;window.choose=function(i,j){oldSelect(i,j);applyFilter()};updateDates();applyFilter();})();